verification_tests:
from target import parse_supplier_rows


def test_quoted_field_with_comma_is_preserved():
    assert parse_supplier_rows('sku,desc\nA,"10x20, blue"\n') == [
        {"sku": "A", "desc": "10x20, blue"}
    ]


def test_simple_row_is_parsed():
    assert parse_supplier_rows("sku,desc\nA,blue\n") == [{"sku": "A", "desc": "blue"}]


def test_escaped_quotes_are_decoded():
    assert parse_supplier_rows('sku,desc\nA,"say ""hi"""\n') == [
        {"sku": "A", "desc": 'say "hi"'}
    ]
